//! Gap #3 MCP surface: typed modifiers, shape modifiers, layer styles. Every feature here is a tool; nothing is GUI-only.
use super::kit::*;
use crate::keyframe::{Op, Prop};
use crate::model::{Effect, Source};
use std::collections::BTreeMap;

fn kind_of(o: &Op) -> &'static str { match o { Op::Wiggle { .. } => "wiggle", Op::LoopOut { .. } | Op::LoopIn { .. } => "loop", Op::Sin { .. } => "sin", Op::Inertia { .. } => "inertia", Op::Bounce { .. } => "bounce", Op::Overshoot { .. } => "overshoot", Op::PosterizeTime { .. } => "posterize_time", Op::Clamp { .. } => "clamp", Op::Round { .. } => "round", Op::Spring { .. } => "spring", Op::NoiseImpulse { .. } => "noise_impulse", Op::Bezier { .. } => "bezier" } }
fn hash_seed(s: &str) -> u64 { let mut h: u64 = 0xcbf29ce484222325; for b in s.bytes() { h ^= b as u64; h = h.wrapping_mul(0x100000001b3); } h }
fn prop_of<'a>(ss: &'a mut Session, a: &Value) -> Result<&'a mut Prop, String> {
    let cid = str_arg(a, "clip_id")?.to_string(); let k = str_arg(a, "property")?.to_string(); let eid = a.get("effect_id").and_then(|v| v.as_str()).map(String::from);
    let c = ss.project.find_clip_mut(&cid).ok_or(format!("no such clip '{cid}'"))?;
    match eid { Some(id) => Ok(c.effects.iter_mut().find(|x| x.id == id).ok_or("no such effect")?.params.entry(k).or_insert(Prop::new(0.0))), None => c.props.get_mut(&k).ok_or(format!("no such property '{k}'")) }
}
/// Read-only lookup: never creates a property (a read tool must not change the project, or undo would miss it).
fn prop_peek<'a>(ss: &'a Session, a: &Value) -> Result<&'a Prop, String> {
    let cid = str_arg(a, "clip_id")?; let k = str_arg(a, "property")?; let eid = a.get("effect_id").and_then(|v| v.as_str());
    let c = ss.project.tracks.iter().flat_map(|t| t.clips.iter()).find(|c| c.id == cid).ok_or(format!("no such clip '{cid}'"))?;
    match eid { Some(id) => c.effects.iter().find(|x| x.id == id).ok_or("no such effect")?.params.get(k).ok_or(format!("no such effect param '{k}'")), None => c.props.get(k).ok_or(format!("no such property '{k}'")) }
}
fn within(a: &Value, k: &str, d: f64, lo: f64, hi: f64) -> Result<f64, String> { let v = opt_num(a, k, d); if v.is_finite() && v >= lo && v <= hi { Ok(v) } else { Err(format!("'{k}' must be in {lo}..{hi}, got {v}")) } }
fn find_clip<'a>(ss: &'a mut Session, a: &Value) -> Result<&'a mut crate::model::Clip, String> { let cid = str_arg(a, "clip_id")?.to_string(); ss.project.find_clip_mut(&cid).ok_or(format!("no such clip '{cid}'")) }
fn spec_list(table: &[(&str, &str, &[(&str, f64)])]) -> Value { json!(table.iter().map(|(k, d, ps)| json!({"kind": k, "description": d, "params": ps.iter().map(|(n, v)| json!({"name": n, "default": v})).collect::<Vec<_>>()})).collect::<Vec<_>>()) }
fn set_effect(c: &mut crate::model::Clip, kind: &str, id: Option<String>, a: &Value, table: &[(&str, &str, &[(&str, f64)])], pre: &str) -> Result<String, String> {
    let (_, _, defs) = table.iter().find(|(k, _, _)| *k == kind).ok_or(format!("unknown {pre} '{kind}'; see the list tool"))?;
    let mut params = BTreeMap::new(); for (n, d) in defs.iter() { let v = a.get("params").and_then(|p| p.get(*n)).map(|v| v.as_f64().filter(|x| x.is_finite()).ok_or(format!("param '{n}' must be a finite number"))).transpose()?.unwrap_or(*d); params.insert(n.to_string(), Prop::new(v)); }
    if let Some(p) = a.get("params").and_then(|p| p.as_object()) { for k in p.keys() { if !defs.iter().any(|(n, _)| n == k) { return Err(format!("unknown param '{k}' for {kind}")); } } }
    let mut strings = BTreeMap::new(); if let Some(o) = a.get("strings").and_then(|v| v.as_object()) { for (k, v) in o { strings.insert(k.clone(), v.as_str().ok_or("strings values must be strings")?.to_string()); } }
    if let Some(i) = id.as_ref().and_then(|id| c.effects.iter().position(|e| &e.id == id)) { c.effects[i].params = params; c.effects[i].strings = strings; return Ok(c.effects[i].id.clone()); }
    let eid = id.unwrap_or_else(|| format!("{kind}-{}", c.effects.len() + 1)); c.effects.push(Effect { id: eid.clone(), kind: kind.into(), params, strings }); Ok(eid)
}

pub fn commands() -> Vec<Command> { vec![
    Command { name: "add_modifier", description: "Typed property modifier (replaces a same-kind modifier, so calls are idempotent). kind: wiggle {freq Hz 0..60, amp, octaves 1-8, seed; default seed is derived from clip+property so layers never wiggle in lockstep}, loop {mode cycle|pingpong|offset|continue, direction out|in|both}, bounce {amp 0..2 fraction of last segment, freq Hz, decay 1/s; rebounds toward the previous value after the last key}, overshoot {amp fraction, freq, decay; damped spring past every key}. Works on any clip property or effect param (effect_id). Needs keyframes for loop/bounce/overshoot.", mutates: true,
        schema: obj(vec![("clip_id", s("clip")), ("property", s("property or effect param")), ("effect_id", s("optional effect")), ("kind", json!({"type":"string","enum":["wiggle","loop","bounce","overshoot"]})), ("freq", n("Hz")), ("amp", n("amplitude")), ("octaves", n("1-8")), ("seed", n("integer seed")), ("mode", s("cycle|pingpong|offset|continue")), ("direction", s("out|in|both")), ("decay", n("1/s"))], &["clip_id","property","kind"]),
        run: |ss, a| { let kind = str_arg(a, "kind")?.to_string(); let cid = str_arg(a, "clip_id")?.to_string(); let prop = str_arg(a, "property")?.to_string();
            let ops: Vec<Op> = match kind.as_str() {
                "wiggle" => { let seed = a.get("seed").and_then(|v| v.as_u64()).unwrap_or_else(|| hash_seed(&format!("{cid}/{prop}"))); vec![Op::Wiggle { freq: within(a, "freq", 2.0, 0.0, 60.0)?, amp: within(a, "amp", 10.0, -1e6, 1e6)?, octaves: within(a, "octaves", 1.0, 1.0, 8.0)? as u32, seed, shift: 0.0 }] }
                "loop" => { let mode = a.get("mode").and_then(|v| v.as_str()).unwrap_or("cycle").to_string(); if !["cycle","pingpong","offset","continue"].contains(&mode.as_str()) { return Err(format!("mode must be cycle|pingpong|offset|continue, got '{mode}'")); }
                    match a.get("direction").and_then(|v| v.as_str()).unwrap_or("out") { "out" => vec![Op::LoopOut { mode }], "in" => vec![Op::LoopIn { mode }], "both" => vec![Op::LoopOut { mode: mode.clone() }, Op::LoopIn { mode }], d => return Err(format!("direction must be out|in|both, got '{d}'")) } }
                "bounce" => vec![Op::Bounce { amp: within(a, "amp", 0.3, 0.0, 2.0)?, freq: within(a, "freq", 3.0, 0.1, 30.0)?, decay: within(a, "decay", 5.0, 0.0, 100.0)? }],
                "overshoot" => vec![Op::Overshoot { amp: within(a, "amp", 0.2, 0.0, 2.0)?, freq: within(a, "freq", 3.0, 0.1, 30.0)?, decay: within(a, "decay", 6.0, 0.0, 100.0)? }],
                o => return Err(format!("unknown modifier kind '{o}'")) };
            let pr = prop_of(ss, a)?; if kind != "wiggle" && pr.keys.len() < 2 && kind != "loop" { return Err(format!("'{kind}' needs at least 2 keyframes on the property")); }
            pr.expr.retain(|o| kind_of(o) != kind); pr.expr.extend(ops);
            Ok(json!({"clip_id": cid, "property": prop, "modifiers": pr.expr.iter().map(kind_of).collect::<Vec<_>>()})) } },
    Command { name: "list_modifiers", description: "List the modifiers/expression ops on a property (kind + full parameters).", mutates: false,
        schema: obj(vec![("clip_id", s("clip")), ("property", s("property or effect param")), ("effect_id", s("optional effect"))], &["clip_id","property"]),
        run: |ss, a| { let pr = prop_peek(ss, a)?; Ok(json!({"modifiers": pr.expr.iter().map(|o| json!({"kind": kind_of(o), "op": o})).collect::<Vec<_>>(), "keyframes": pr.keys.len()})) } },
    Command { name: "remove_modifier", description: "Remove modifiers of one kind (wiggle|loop|bounce|overshoot|sin|inertia|posterize_time|clamp|round) from a property, or all when kind is omitted.", mutates: true,
        schema: obj(vec![("clip_id", s("clip")), ("property", s("property or effect param")), ("effect_id", s("optional effect")), ("kind", s("modifier kind; omit = all"))], &["clip_id","property"]),
        run: |ss, a| { let k = a.get("kind").and_then(|v| v.as_str()).map(String::from); let pr = prop_of(ss, a)?; let before = pr.expr.len(); match &k { Some(k) => pr.expr.retain(|o| kind_of(o) != k), None => pr.expr.clear() } Ok(json!({"removed": before - pr.expr.len(), "remaining": pr.expr.len()})) } },
    Command { name: "list_shape_modifiers", description: "List available shape modifier kinds with parameters and defaults (trim, repeater, offset, merge, gradient stroke).", mutates: false, schema: obj(vec![], &[]), run: |_, _| Ok(json!({"modifiers": spec_list(crate::shapemods::KINDS)})) },
    Command { name: "add_shape_modifier", description: "Add or update a vector shape modifier (trim, repeater, offset, merge, gradient stroke, gradient fill) on a Shape clip. Add (or update by effect_id) a vector shape modifier on a Shape clip: trim {start,end,offset}, repeater {copies,dx,dy,rotation,scale}, offset {amount}, merge {w,h,dx,dy,sides,corner_radius + strings.shape/mode}, gradient_stroke/gradient_fill {r1..b2,angle}. Params are keyframable afterwards with set_keyframe using effect_id (e.g. animate trim end 0->1 for a draw-on). Modifiers apply in the order added.", mutates: true,
        schema: obj(vec![("clip_id", s("Shape clip")), ("kind", json!({"type":"string","enum":["trim","repeater","offset","merge","gradient_stroke","gradient_fill"]})), ("effect_id", s("existing modifier id to update")), ("params", json!({"type":"object","description":"param name -> number"})), ("strings", json!({"type":"object","description":"merge: shape (rect|ellipse|polygon|line), mode (union|subtract|intersect|exclude)"}))], &["clip_id","kind"]),
        run: |ss, a| { let kind = format!("shape_{}", str_arg(a, "kind")?); let eid = a.get("effect_id").and_then(|v| v.as_str()).map(String::from); let c = find_clip(ss, a)?; if !matches!(c.source, Source::Shape { .. }) { return Err("add_shape_modifier needs a Shape clip (see add_shape)".into()); }
            if kind == "shape_merge" { let st = a.get("strings"); for (k, ok) in [("shape", &["rect","ellipse","polygon","line","path"][..]), ("mode", &["union","subtract","intersect","exclude"][..])] { if let Some(v) = st.and_then(|s| s.get(k)).and_then(|v| v.as_str()) { if !ok.contains(&v) { return Err(format!("merge strings.{k} must be one of {ok:?}, got '{v}'")); } } } }
            if kind == "shape_merge" && a.get("strings").and_then(|s| s.get("shape")).and_then(|v| v.as_str()) == Some("path") { let d = a.get("strings").and_then(|s| s.get("d")).and_then(|v| v.as_str()).ok_or("merge with shape=path needs strings.d (SVG path)")?; crate::paths::Path::parse(d, false)?; }
            if kind == "shape_repeater" { if let Some(c) = a.get("params").and_then(|p| p.get("copies")).and_then(|v| v.as_f64()) { if !(1.0..=64.0).contains(&c) { return Err("repeater copies must be 1..64".into()); } } }
            let id = set_effect(c, &kind, eid, a, crate::shapemods::KINDS, "shape modifier")?; Ok(json!({"effect_id": id, "kind": kind, "note": "trim and gradient_stroke act on the stroke: set stroke_width > 0 on the shape"})) } },
    Command { name: "remove_shape_modifier", description: "Remove a shape modifier by effect_id.", mutates: true, schema: obj(vec![("clip_id", s("Shape clip")), ("effect_id", s("modifier id"))], &["clip_id","effect_id"]),
        run: |ss, a| { let id = str_arg(a, "effect_id")?.to_string(); let c = find_clip(ss, a)?; let n = c.effects.len(); c.effects.retain(|e| !(e.id == id && e.kind.starts_with("shape_"))); if c.effects.len() == n { return Err(format!("no shape modifier '{id}'")); } Ok(json!({"removed": id})) } },
    Command { name: "list_layer_styles", description: "List layer styles (inner_shadow, bevel, stroke) with parameters and defaults. drop_shadow, outline and outer_glow already exist as effects.", mutates: false, schema: obj(vec![], &[]), run: |_, _| Ok(json!({"styles": spec_list(crate::layerstyles::STYLES)})) },
    Command { name: "set_layer_style", description: "Add or update a layer style on any alpha layer: inner shadow, bevel, stroke, glow and more. Add or update (by effect_id, else one per style kind) a layer style on any alpha layer: inner_shadow {dx,dy,blur,choke,opacity,r,g,b}, bevel {depth,size,angle,highlight,shadow}, stroke {width,opacity,r,g,b + strings.position inside|center|outside}. Px values scale with canvas height (720p reference). Params are keyframable via set_keyframe with effect_id.", mutates: true,
        schema: obj(vec![("clip_id", s("clip")), ("style", json!({"type":"string","enum":["inner_shadow","bevel","stroke"]})), ("effect_id", s("existing style id to update")), ("params", json!({"type":"object","description":"param name -> number"})), ("strings", json!({"type":"object","description":"stroke: position"}))], &["clip_id","style"]),
        run: |ss, a| { let kind = format!("ls_{}", str_arg(a, "style")?); if let Some(v) = a.get("strings").and_then(|s| s.get("position")).and_then(|v| v.as_str()) { if !["inside","center","outside"].contains(&v) { return Err(format!("position must be inside|center|outside, got '{v}'")); } }
            let eid = a.get("effect_id").and_then(|v| v.as_str()).map(String::from).or_else(|| Some(kind.clone())); let c = find_clip(ss, a)?; let id = set_effect(c, &kind, eid, a, crate::layerstyles::STYLES, "layer style")?; Ok(json!({"effect_id": id, "kind": kind})) } },
    Command { name: "remove_layer_style", description: "Remove a layer style by effect_id.", mutates: true, schema: obj(vec![("clip_id", s("clip")), ("effect_id", s("style id"))], &["clip_id","effect_id"]),
        run: |ss, a| { let id = str_arg(a, "effect_id")?.to_string(); let c = find_clip(ss, a)?; let n = c.effects.len(); c.effects.retain(|e| !(e.id == id && e.kind.starts_with("ls_"))); if c.effects.len() == n { return Err(format!("no layer style '{id}'")); } Ok(json!({"removed": id})) } },
] }
